import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Parameter Dasar","description":"","frontmatter":{"title":"Parameter Dasar"},"headers":[],"relativePath":"byok/parameter-dasar.md","filePath":"byok/parameter-dasar.md"}`),a={name:`byok/parameter-dasar.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="parameter-dasar-di-panel-byok" tabindex="-1">Parameter Dasar di Panel BYOK <a class="header-anchor" href="#parameter-dasar-di-panel-byok" aria-label="Permalink to “Parameter Dasar di Panel BYOK”">​</a></h1><p>Setelah BYOK aktif, buka kartu <strong>&quot;Opsi Lanjutan&quot;</strong> di pengaturan engine. Kamu tidak harus mengerti semuanya — semua parameter punya nilai default yang berperilaku baik. Tapi pahami dua yang paling penting: <code>max_tokens</code> dan <code>context_window</code>.</p><h2 id="max-tokens-payload-max-tokens" tabindex="-1">Max Tokens (<code>payload: max_tokens</code>) <a class="header-anchor" href="#max-tokens-payload-max-tokens" aria-label="Permalink to “Max Tokens (payload: max_tokens)”">​</a></h2><p>Jumlah token maksimum yang boleh dihasilkan AI untuk satu jawaban (default 2048). Nilai ini punya <strong>peran ganda</strong>:</p><ol><li><strong>Dikirim ke provider sebagai <code>max_tokens</code></strong> — membatasi panjang jawaban.</li><li><strong>Dipotong dari Context Window sebagai <em>Reserved Output</em></strong> — menjamin jawaban selalu punya &quot;ruang jalan&quot; dan tidak pernah terpotong di akhir window.</li></ol><p>Konsekuensinya:</p><ul><li>Angka lebih besar → jawaban bisa lebih panjang, tetapi riwayat chat yang bisa muat jadi <strong>lebih sedikit</strong>.</li><li>Angka lebih kecil → jawaban pendek, tetapi memori riwayat makin lega.</li></ul><h2 id="context-window-payload-context-window" tabindex="-1">Context Window (<code>payload: context_window</code>) <a class="header-anchor" href="#context-window-payload-context-window" aria-label="Permalink to “Context Window (payload: context_window)”">​</a></h2><p><em>Budget</em> total satu request: system prompt + memori + riwayat + ruang jawaban; semuanya harus muat di angka ini.</p><ul><li><strong>0 (Auto)</strong> — nilai default. Mikazuki mendeteksi otomatis per model (Gemini/Claude: 128K, DeepSeek: 64K, lainnya: 32K).</li><li>Nilai lain — dipakai mentah, hingga <strong>1.000.000 token</strong> untuk model <em>long context</em>.</li><li>Preset cepat tersedia sebagai chip: <code>Auto</code> <code>8K</code> <code>32K</code> <code>128K</code> <code>1M</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Mengapa ini penting?</p><p>Context window kecil → riwayat chat terpangkas agresif → karakter &quot;pelupa&quot;. Context window sesuai kapasitas asli model → karakter bisa mengingat percakapan jauh ke belakang. Jika memakai model long-context (mis. Gemini 1M), set <code>context_window</code> ke <code>1M</code>.</p></div><h2 id="parameter-kreativitas" tabindex="-1">Parameter Kreativitas <a class="header-anchor" href="#parameter-kreativitas" aria-label="Permalink to “Parameter Kreativitas”">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Rentang</th><th>Efek</th></tr></thead><tbody><tr><td><code>stream</code></td><td>boolean</td><td>Mengirim teks berkarakter-per-karakter (<em>streaming</em>). Default aktif.</td></tr><tr><td><code>max_tokens</code></td><td>integer</td><td>Lihat penjelasan di atas.</td></tr><tr><td><code>temperature</code></td><td>0.0–2.0</td><td>Makin tinggi = jawaban makin liar/imajinatif. Makin rendah = makin kering, stabil. Default 0.85.</td></tr><tr><td><code>top_p</code></td><td>0.0–1.0</td><td>Alternatif pengendalian &#39;fokus&#39; sampling. Default 0.95.</td></tr><tr><td><code>repetition_penalty</code></td><td>0.0–2.0</td><td>Menghukum pengulangan frasa yang sama. Nonaktif (0) atau 1.1 default.</td></tr><tr><td><code>presence_penalty</code></td><td>0.0–2.0</td><td>Mendorong topik / kata baru. Nonaktif (0) default.</td></tr></tbody></table><h2 id="advanced-payload" tabindex="-1">Advanced Payload <a class="header-anchor" href="#advanced-payload" aria-label="Permalink to “Advanced Payload”">​</a></h2><p>Bagi yang ingin mendorong provider lebih jauh, panel <strong>Advanced Payload</strong> memungkinkan menambahkan field apa pun ke request (mis. <code>frequency_penalty</code>, <code>tool_choice</code>, atau parameter khusus provider). Field berikut sudah direservasi dan tak dapat dipakai ulang: <code>stream</code>, <code>max_tokens</code>, <code>context_window</code>, <code>temperature</code>, <code>top_p</code>, <code>repetition_penalty</code>, <code>presence_penalty</code>.</p><h2 id="selanjutnya" tabindex="-1">Selanjutnya <a class="header-anchor" href="#selanjutnya" aria-label="Permalink to “Selanjutnya”">​</a></h2><ul><li>Belum mengaktifkan BYOK? Mulai dari <a href="./instalasi.html">Instalasi &amp; Aktivasi</a>.</li><li>Kembali ke <a href="./">Pengenalan BYOK</a> untuk gambaran besar mode BYOK.</li></ul>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};